// StudentProfile.jsx

import { useState } from "react";
import StudentLayout from "./StudentLayout";

const ALL_SKILLS = ["React","Vue","Angular","Node.js","Express","Django","FastAPI","Laravel","Python","Java","PHP","C++","SQL","PostgreSQL","MongoDB","Docker","Git","Linux","Flutter","TypeScript","Redis","Kubernetes","GraphQL","REST API","TensorFlow","Figma"];

const initProfile = {
  firstName:"Amira", lastName:"Benali",
  email:"amira.benali@ifa.edu.dz",
  phone:"+213 555 123 456",
  university:"IFA — Institut de Formation en Algorithmique",
  department:"Informatique",
  level:"L3",
  wilaya:"Alger",
  github:"https://github.com/amira-benali",
  portfolio:"",
  linkedin:"",
  bio:"Passionate CS student at IFA with a strong interest in full-stack web development and cloud technologies. Looking for a 6-month internship where I can contribute to real-world projects.",
  skills:["React","Node.js","Python","SQL","Git","Docker"],
  languages:[
    { lang:"Arabic",  level:"Native"    },
    { lang:"French",  level:"Fluent"    },
    { lang:"English", level:"Professional"},
  ],
  education:[
    { degree:"Licence — Informatique",     school:"IFA", year:"2023 — Present" },
    { degree:"Baccalauréat — Sciences",    school:"Lycée Bouâlem Hassaïne", year:"2022" },
  ],
};

const LEVELS = ["A1","A2","B1","B2","C1","Native","Fluent","Professional"];
const WILAYAS = ["Alger","Oran","Constantine","Annaba","Béjaïa","Tizi Ouzou","Blida","Sétif","Tlemcen","Batna"];

export default function StudentProfile() {
  const [profile, setProfile] = useState(initProfile);
  const [editing, setEditing] = useState(false);
  const [saved, setSaved]     = useState(false);
  const [draft, setDraft]     = useState(initProfile);
  const [activeTab, setActiveTab] = useState("info");

  const upd = (k,v) => setDraft(d=>({...d,[k]:v}));

  const toggleSkill = s => {
    setDraft(d=>({
      ...d,
      skills: d.skills.includes(s) ? d.skills.filter(x=>x!==s) : [...d.skills, s]
    }));
  };

  const startEdit = () => { setDraft({...profile}); setEditing(true); setSaved(false); };
  const cancel    = () => { setEditing(false); };
  const save      = () => { setProfile({...draft}); setEditing(false); setSaved(true); setTimeout(()=>setSaved(false),3000); };

  // دالة لحساب النسبة المئوية للإكمال
  const calculateCompletion = (data) => {
    let score = 0;
    if (data.firstName && data.lastName) score += 15;
    if (data.email)       score += 10;
    if (data.phone)       score += 5;
    if (data.bio)         score += 15;
    if (data.skills.length >= 3) score += 20;
    if (data.github)      score += 20;
    if (data.portfolio)   score += 10;
    if (data.linkedin)    score += 5;
    return score;
  };

  const currentCompletion = editing ? calculateCompletion(draft) : calculateCompletion(profile);

  return (
    <StudentLayout active="profile">
      <div className="p-5 md:p-8 max-w-4xl mx-auto">

        {/* Header */}
        <div className="anim-fade-up flex items-start justify-between flex-wrap gap-3 mb-6">
          <div>
            <p className="text-xs font-semibold text-blue-500 uppercase tracking-widest mb-1">Profile</p>
            <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">My profile</h1>
            <p className="text-slate-400 text-sm font-light mt-0.5">Your digital CV visible to companies</p>
          </div>
          <div className="flex gap-2 items-center">
            {saved && <span className="text-xs text-emerald-600 font-semibold bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-200">✓ Saved!</span>}
            {!editing
              ? <button onClick={startEdit} className="shimmer-btn text-white text-sm font-semibold px-5 py-2.5 rounded-xl">Edit profile</button>
              : (<div className="flex gap-2">
                  <button onClick={cancel} className="text-sm font-medium text-slate-600 border border-slate-200 px-4 py-2.5 rounded-xl hover:bg-slate-50 transition-colors">Cancel</button>
                  <button onClick={save}   className="shimmer-btn text-white text-sm font-semibold px-5 py-2.5 rounded-xl">Save changes</button>
                </div>
              )
            }
          </div>
        </div>

        {/* Profile header card */}
        <div className="anim-fade-up anim-d1 card border border-slate-200 p-5 mb-5">
          <div className="flex flex-col md:flex-row gap-4 items-start">
            {/* Avatar */}
            <div className="relative">
              <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-blue-400 to-blue-700 flex items-center justify-center text-2xl font-bold text-white font-syne shrink-0">
                {profile.firstName[0]}{profile.lastName[0]}
              </div>
              {editing && (
                <button className="absolute -bottom-1 -right-1 w-7 h-7 bg-white border border-slate-200 rounded-lg flex items-center justify-center text-xs shadow-sm hover:bg-slate-50">
                  📷
                </button>
              )}
            </div>

            {/* Info */}
            <div className="flex-1">
              <h2 className="font-syne font-extrabold text-slate-900 text-xl">{profile.firstName} {profile.lastName}</h2>
              <p className="text-slate-500 text-sm">{profile.level} {profile.department} · {profile.university}</p>
              <div className="flex flex-wrap gap-2 mt-2">
                <span className="badge badge-blue">📍 {profile.wilaya}</span>
                {profile.github && <a href={profile.github} target="_blank" rel="noreferrer" className="badge badge-slate hover:border-blue-400 hover:text-blue-500 transition-colors">🔗 GitHub</a>}
                {profile.portfolio && <a href={profile.portfolio} target="_blank" rel="noreferrer" className="badge badge-slate">🌐 Portfolio</a>}
              </div>
            </div>

            {/* Completion */}
            <div className="md:text-right shrink-0">
              <div className="font-syne font-extrabold text-3xl text-blue-600">{currentCompletion}%</div>
              <div className="text-xs text-slate-400 mb-2">Profile complete</div>
              <div className="h-2 w-24 bg-slate-100 rounded-full overflow-hidden md:ml-auto">
                <div className="progress-bar-inner h-full bg-blue-500 transition-all duration-500" style={{width:`${currentCompletion}%`}} />
              </div>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="anim-fade-up anim-d2 flex gap-1 bg-slate-100 rounded-xl p-1 w-fit mb-5">
          {[{id:"info",label:"Personal info"},{id:"skills",label:"Skills"},{id:"cv",label:"CV Preview"}].map(t=>(
            <button key={t.id} onClick={()=>setActiveTab(t.id)} className={`tab-btn ${activeTab===t.id?"active":"inactive"}`}>{t.label}</button>
          ))}
        </div>

        {/* ── TAB: INFO ── */}
        {activeTab === "info" && (
          <div className="anim-fade-up space-y-4">
            {/* Personal */}
            <div className="card border border-slate-200 p-5">
              <h3 className="font-syne font-bold text-slate-800 text-base mb-4">Personal information</h3>
              <div className="grid md:grid-cols-2 gap-4">
                {[
                  { label:"First name",  key:"firstName",  placeholder:"Amira"   },
                  { label:"Last name",   key:"lastName",   placeholder:"Benali"  },
                  { label:"Email",       key:"email",      placeholder:"name@ifa.edu.dz", type:"email" },
                  { label:"Phone",       key:"phone",      placeholder:"+213 555 000 000" },
                  ].map(({label,key,placeholder,type="text"})=>(
                  <div key={key}>
                    <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">{label}</label>
                    {editing
                      ? <input type={type} value={draft[key] || ""} onChange={e=>upd(key,e.target.value)} placeholder={placeholder} className="input-field" />
                      : <p className="text-sm text-slate-700 font-medium py-2 px-3 bg-slate-50 rounded-lg">{profile[key] || <span className="text-slate-400">Not set</span>}</p>
                    }
                  </div>
                ))}
              </div>
            </div>

            {/* Academic */}
            <div className="card border border-slate-200 p-5">
              <h3 className="font-syne font-bold text-slate-800 text-base mb-4">Academic information</h3>
              <div className="grid md:grid-cols-2 gap-4">
                {[
                  { label:"University", key:"university", placeholder:"IFA, USTHB..." },
                  { label:"Department", key:"department", placeholder:"Informatique" },
                  { label:"Level",      key:"level",      placeholder:"L3, M1, M2..." },
                  { label:"Wilaya",     key:"wilaya",     isSelect:true },
                ].map(({label,key,placeholder,isSelect})=>(
                  <div key={key}>
                    <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">{label}</label>
                    {editing
                      ? isSelect
                        ? <select value={draft[key]} onChange={e=>upd(key,e.target.value)} className="input-field">
                            {WILAYAS.map(w=><option key={w} value={w}>{w}</option>)}
                          </select>
                        : <input value={draft[key] || ""} onChange={e=>upd(key,e.target.value)} placeholder={placeholder} className="input-field" />
                      : <p className="text-sm text-slate-700 font-medium py-2 px-3 bg-slate-50 rounded-lg">{profile[key] || <span className="text-slate-400">Not set</span>}</p>
                    }
                  </div>
                ))}
              </div>
            </div>

            {/* Bio */}
            <div className="card border border-slate-200 p-5">
              <h3 className="font-syne font-bold text-slate-800 text-base mb-4">Bio / Presentation</h3>
              {editing
                ? <textarea rows={4} value={draft.bio || ""} onChange={e=>upd("bio",e.target.value)} placeholder="Describe yourself, your interests and goals..." className="input-field resize-none" />
                : <p className="text-sm text-slate-600 font-light leading-relaxed">{profile.bio || <span className="text-slate-400">No bio yet.</span>}</p>
              }
            </div>

            {/* Links */}
            <div className="card border border-slate-200 p-5">
              <h3 className="font-syne font-bold text-slate-800 text-base mb-4">Links</h3>
              <div className="space-y-3">
                {[
                  { label:"GitHub",    key:"github",    icon:"🐱", placeholder:"https://github.com/username" },
                  { label:"Portfolio", key:"portfolio", icon:"🌐", placeholder:"https://your-portfolio.com" },
                  { label:"LinkedIn",  key:"linkedin",  icon:"💼", placeholder:"https://linkedin.com/in/username" },
                ].map(({label,key,icon,placeholder})=>(
                  <div key={key}>
                    <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">{icon} {label}</label>
                    {editing
                      ? <input value={draft[key] || ""} onChange={e=>upd(key,e.target.value)} placeholder={placeholder} className="input-field" />: profile[key]
                        ? <a href={profile[key]} target="_blank" rel="noreferrer" className="text-sm text-blue-600 hover:underline font-medium py-2 px-3 bg-blue-50 rounded-lg block truncate">{profile[key]}</a>
                        : <p className="text-sm text-slate-400 py-2 px-3 bg-slate-50 rounded-lg">Not set</p>
                    }
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* ── TAB: SKILLS ── */}
        {activeTab === "skills" && (
          <div className="anim-fade-up space-y-4">
            <div className="card border border-slate-200 p-5">
              <h3 className="font-syne font-bold text-slate-800 text-base mb-1">Technical skills</h3>
              <p className="text-xs text-slate-400 mb-4">{editing ? "Click to add or remove skills" : `${profile.skills.length} skills selected`}</p>
              <div className="flex flex-wrap gap-2">
                {(editing ? ALL_SKILLS : profile.skills).map(s => {
                  const isSelected = editing ? draft.skills.includes(s) : true;
                  return (
                    <span
                      key={s}
                      onClick={() => editing && toggleSkill(s)}
                      className={`text-sm px-3 py-1.5 rounded-full border font-medium transition-all select-none ${
                        editing ? "cursor-pointer" : ""
                      } ${
                        isSelected
                          ? "bg-blue-600 border-blue-600 text-white"
                          : "bg-white border-slate-200 text-slate-500 hover:border-blue-300 hover:text-blue-600"
                      }`}
                    >
                      {s}
                    </span>
                  );
                })}
              </div>
            </div>

            {/* Languages */}
            <div className="card border border-slate-200 p-5">
              <h3 className="font-syne font-bold text-slate-800 text-base mb-4">Languages</h3>
              <div className="space-y-3">
                {(editing ? draft : profile).languages.map((l, i) => (
                  <div key={i} className="flex items-center justify-between py-2 border-b border-slate-100 last:border-0">
                    <span className="text-sm font-semibold text-slate-700">{l.lang}</span>
                    {editing
                      ? <select value={l.level} onChange={e => {
                          const langs = [...draft.languages];
                          langs[i] = {...langs[i], level: e.target.value};
                          setDraft(d=>({...d, languages:langs}));
                        }} className="input-field w-40 py-1 text-xs">
                          {LEVELS.map(lv=><option key={lv} value={lv}>{lv}</option>)}
                        </select>
                      : <span className="badge badge-blue">{l.level}</span>
                    }
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* ── TAB: CV PREVIEW ── */}
        {activeTab === "cv" && (
          <div className="anim-fade-up">
            <div className="card border border-slate-200 p-6 bg-white shadow-sm" style={{fontFamily:"'DM Sans', sans-serif"}}>
              {/* CV header */}
              <div className="flex justify-between items-start pb-5 mb-5 border-b-2 border-slate-900">
                <div>
                  <h2 className="font-syne font-extrabold text-2xl text-slate-900">{profile.firstName} {profile.lastName}</h2>
                  <p className="text-slate-600 text-sm mt-0.5">{profile.level} {profile.department} — {profile.university}</p>
                  <div className="flex flex-wrap gap-3 mt-2 text-xs text-slate-500"><span>📧 {profile.email}</span>
                    {profile.phone && <span>📱 {profile.phone}</span>}
                    {profile.github && <span>🐱 GitHub</span>}
                  </div>
                </div>
                <div className="w-14 h-14 rounded-xl bg-gradient-to-br from-blue-400 to-blue-700 flex items-center justify-center text-xl font-bold text-white font-syne">
                  {profile.firstName[0]}{profile.lastName[0]}
                </div>
              </div>

              {/* Bio */}
              {profile.bio && (
                <div className="mb-5">
                  <h4 className="font-syne font-bold text-slate-800 text-sm uppercase tracking-widest mb-2 flex items-center gap-2">
                    <span className="w-4 h-0.5 bg-blue-500 inline-block" />About
                  </h4>
                  <p className="text-sm text-slate-600 font-light leading-relaxed">{profile.bio}</p>
                </div>
              )}

              {/* Skills */}
              <div className="mb-5">
                <h4 className="font-syne font-bold text-slate-800 text-sm uppercase tracking-widest mb-2 flex items-center gap-2">
                  <span className="w-4 h-0.5 bg-blue-500 inline-block" />Technical Skills
                </h4>
                <div className="flex flex-wrap gap-1.5">
                  {profile.skills.map(s=>(
                    <span key={s} className="text-xs bg-slate-100 text-slate-700 px-2.5 py-1 rounded font-medium">{s}</span>
                  ))}
                </div>
              </div>

              {/* Education */}
              <div className="mb-5">
                <h4 className="font-syne font-bold text-slate-800 text-sm uppercase tracking-widest mb-2 flex items-center gap-2">
                  <span className="w-4 h-0.5 bg-blue-500 inline-block" />Education
                </h4>
                {profile.education.map((e,i)=>(
                  <div key={i} className="flex justify-between text-sm py-1.5 border-b border-slate-100 last:border-0">
                    <div>
                      <div className="font-semibold text-slate-800">{e.degree}</div>
                      <div className="text-xs text-slate-500">{e.school}</div>
                    </div>
                    <div className="text-xs text-slate-400 shrink-0">{e.year}</div>
                  </div>
                ))}
              </div>

              {/* Languages */}
              <div>
                <h4 className="font-syne font-bold text-slate-800 text-sm uppercase tracking-widest mb-2 flex items-center gap-2">
                  <span className="w-4 h-0.5 bg-blue-500 inline-block" />Languages
                </h4>
                <div className="flex flex-wrap gap-3">
                  {profile.languages.map((l,i)=>(
                    <div key={i} className="text-sm text-slate-600"><strong className="text-slate-800">{l.lang}</strong> — {l.level}</div>
                  ))}
                </div>
              </div>
            </div>
            <button className="mt-3 w-full shimmer-btn text-white text-sm font-semibold py-3 rounded-xl">
              📄 Export as PDF
            </button>
          </div>
        )}
      </div>
    </StudentLayout>
  );
}
